t = int(input())

lo, hi = 0, len(nums) - 1
answer = -1
while lo <= hi:
    mid = (lo + hi) // 2
    if nums[mid] == t:
        answer = mid
        break
    if nums[lo] <= nums[mid]:               # left half is sorted
        if nums[lo] <= t < nums[mid]:
            hi = mid - 1
        else:
            lo = mid + 1
    else:                                   # right half is sorted
        if nums[mid] < t <= nums[hi]:
            lo = mid + 1
        else:
            hi = mid - 1

print(answer)

