nums = [int(x) for x in input().split()]

low, mid, high = 0, 0, len(nums) - 1
while mid <= high:
    if nums[mid] == 0:
        nums[low], nums[mid] = nums[mid], nums[low]
        low += 1
        mid += 1
    elif nums[mid] == 1:
        mid += 1
    else:
        nums[mid], nums[high] = nums[high], nums[mid]
        high -= 1           # do not move mid: check the swapped-in value

print(" ".join(str(x) for x in nums))

n = int(input())
matrix = [[int(x) for x in input().split()] for _ in range(n)]
k = int(input())

lo, hi = matrix[0][0], matrix[n - 1][n - 1]
while lo < hi:
    mid = (lo + hi) // 2
    # count the numbers <= mid, starting from the bottom-left corner
    count = 0
    row, col = n - 1, 0
    while row >= 0 and col < n:
        if matrix[row][col] <= mid:
            count += row + 1
            col += 1
        else:
            row -= 1
    if count >= k:
        hi = mid
    else:
        lo = mid + 1

print(lo)
